{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data/explore.csv')
# within-hospital correlation of each exposure with recovery
exposures = ['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for e in exposures:
    cs=[]
    for h,g in df.groupby('hospital'):
        cs.append(g[[e,'recovery_score']].dropna().corr().iloc[0,1])
    print(f"{e:14s} within-hospital corr: {np.round(cs,3)}")
"}
